`timescale 1ns / 1ps
`default_nettype none

// axil_timer: AXI4-Lite subordinate, 32-bit down-counting timer, level irq.
// Implements the microarchitecture spec prj-ada3a9b9d9.microarchitecture.a1
// (sections 2 to 6). TMR-LOAD-END-EDGE: the pre-edge LOAD value is reloaded.
// Not yet linted, simulated, synthesised or reviewed.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  // ---------------------------------------------------------------- state
  reg                  aw_held_q;
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg                  w_held_q;
  reg [31:0]           w_data_q;
  reg [3:0]            w_strb_q;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [1:0]            rresp_q;
  reg [31:0]           rdata_q;
  reg                  en_q;
  reg                  ie_q;
  reg                  mode_q;
  reg [31:0]           load_q;
  reg [31:0]           count_q;
  reg                  expired_q;

  // ----------------------------------------------------------- next state
  reg                  aw_held_d;
  reg [ADDR_WIDTH-1:0] aw_addr_d;
  reg                  w_held_d;
  reg [31:0]           w_data_d;
  reg [3:0]            w_strb_d;
  reg                  bvalid_d;
  reg [1:0]            bresp_d;
  reg                  rvalid_d;
  reg [1:0]            rresp_d;
  reg [31:0]           rdata_d;
  reg                  en_d;
  reg                  ie_d;
  reg                  mode_d;
  reg [31:0]           load_d;
  reg [31:0]           count_d;
  reg                  expired_d;

  // ------------------------------------------------- channel outputs (flops only)
  wire awready_w = ~aw_held_q & ~bvalid_q;
  wire wready_w  = ~w_held_q  & ~bvalid_q;
  wire arready_w = ~rvalid_q;

  assign s_axil_awready = awready_w;
  assign s_axil_wready  = wready_w;
  assign s_axil_arready = arready_w;
  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rresp   = rresp_q;
  assign s_axil_rdata   = rdata_q;
  assign irq            = expired_q & ie_q;

  // ---------------------------------------------------------------- events
  wire aw_fire = s_axil_awvalid & awready_w;
  wire w_fire  = s_axil_wvalid  & wready_w;
  wire ar_fire = s_axil_arvalid & arready_w;
  wire wr_done = (aw_fire | aw_held_q) & (w_fire | w_held_q);

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
  wire [31:0]           wr_data = w_held_q  ? w_data_q  : s_axil_wdata;
  wire [3:0]            wr_strb = w_held_q  ? w_strb_q  : s_axil_wstrb;

  // ---------------------------------------------------------------- decode
  wire wr_hi_zero;
  wire ar_hi_zero;
  generate
    if (ADDR_WIDTH > 4) begin : g_hi
      assign wr_hi_zero = (wr_addr[ADDR_WIDTH-1:4]       == {(ADDR_WIDTH-4){1'b0}});
      assign ar_hi_zero = (s_axil_araddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
    end else begin : g_nohi
      assign wr_hi_zero = 1'b1;
      assign ar_hi_zero = 1'b1;
    end
  endgenerate

  wire       wr_mapped = (wr_addr[1:0] == 2'b00) & wr_hi_zero;
  wire       ar_mapped = (s_axil_araddr[1:0] == 2'b00) & ar_hi_zero;
  wire [1:0] wr_idx    = wr_addr[3:2];

  wire wr_ctrl  = wr_done & wr_mapped & (wr_idx == 2'd0) & wr_strb[0];
  wire wr_load  = wr_done & wr_mapped & (wr_idx == 2'd1);
  wire wr_stclr = wr_done & wr_mapped & (wr_idx == 2'd3) & wr_strb[0] & wr_data[0];
  wire wr_err   = ~wr_mapped | (wr_idx == 2'd2);
  wire start    = wr_ctrl & wr_data[0];

  // count end: EN 1 and all 32 bits of COUNT are 1 or 0 before the edge
  wire cend = en_q & (count_q[31:1] == 31'd0);

  // ------------------------------------------------------------- read mux
  reg [31:0] rd_mux;
  always @* begin
    case (s_axil_araddr[3:2])
      2'd0:    rd_mux = {29'd0, mode_q, ie_q, en_q};
      2'd1:    rd_mux = load_q;
      2'd2:    rd_mux = count_q;
      2'd3:    rd_mux = {31'd0, expired_q};
      default: rd_mux = 32'd0;
    endcase
  end

  // ------------------------------------------------------ next-state logic
  always @* begin
    aw_held_d = aw_held_q;
    aw_addr_d = aw_addr_q;
    w_held_d  = w_held_q;
    w_data_d  = w_data_q;
    w_strb_d  = w_strb_q;
    bvalid_d  = bvalid_q;
    bresp_d   = bresp_q;
    rvalid_d  = rvalid_q;
    rresp_d   = rresp_q;
    rdata_d   = rdata_q;
    en_d      = en_q;
    ie_d      = ie_q;
    mode_d    = mode_q;
    load_d    = load_q;
    count_d   = count_q;
    expired_d = expired_q;

    // AW / W holding (TMR-ORDER, TMR-READY)
    if (wr_done) begin
      aw_held_d = 1'b0;
      w_held_d  = 1'b0;
    end else begin
      if (aw_fire) begin
        aw_held_d = 1'b1;
        aw_addr_d = s_axil_awaddr;
      end
      if (w_fire) begin
        w_held_d = 1'b1;
        w_data_d = s_axil_wdata;
        w_strb_d = s_axil_wstrb;
      end
    end

    // B channel (TMR-RESPONSE, TMR-SLVERR)
    if (wr_done) begin
      bvalid_d = 1'b1;
      bresp_d  = wr_err ? RESP_SLVERR : RESP_OKAY;
    end else if (bvalid_q && s_axil_bready) begin
      bvalid_d = 1'b0;
    end

    // R channel (TMR-READ-VALUE, TMR-RESPONSE-RDATA-STABLE)
    if (ar_fire) begin
      rvalid_d = 1'b1;
      rdata_d  = ar_mapped ? rd_mux : 32'd0;
      rresp_d  = ar_mapped ? RESP_OKAY : RESP_SLVERR;
    end else if (rvalid_q && s_axil_rready) begin
      rvalid_d = 1'b0;
    end

    // CTRL (TMR-START, TMR-STOP, TMR-ONESHOT, TMR-CTRL-WINS, TMR-RESTART-MODE)
    if (wr_ctrl) begin
      en_d   = wr_data[0];
      ie_d   = wr_data[1];
      mode_d = wr_data[2];
    end else if (cend && !mode_q) begin
      en_d = 1'b0;
    end

    // COUNT (TMR-COUNT, TMR-PERIODIC, TMR-STOP-EDGE, TMR-LOAD-END-EDGE old value)
    if (start) begin
      count_d = load_q;
    end else if (cend) begin
      count_d = mode_q ? load_q : 32'd0;
    end else if (en_q) begin
      count_d = count_q - 32'd1;
    end

    // EXPIRED (TMR-END-BEATS-CLEAR, TMR-STATUS-CLEAR)
    if (cend) begin
      expired_d = 1'b1;
    end else if (wr_stclr) begin
      expired_d = 1'b0;
    end

    // LOAD byte writes (TMR-LOAD)
    if (wr_load) begin
      if (wr_strb[0]) load_d[7:0]   = wr_data[7:0];
      if (wr_strb[1]) load_d[15:8]  = wr_data[15:8];
      if (wr_strb[2]) load_d[23:16] = wr_data[23:16];
      if (wr_strb[3]) load_d[31:24] = wr_data[31:24];
    end
  end

  // -------------------------------------------- registers, synchronous reset
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held_q <= 1'b0;
      aw_addr_q <= {ADDR_WIDTH{1'b0}};
      w_held_q  <= 1'b0;
      w_data_q  <= 32'd0;
      w_strb_q  <= 4'd0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      rvalid_q  <= 1'b0;
      rresp_q   <= RESP_OKAY;
      rdata_q   <= 32'd0;
      en_q      <= 1'b0;
      ie_q      <= 1'b0;
      mode_q    <= 1'b0;
      load_q    <= 32'd0;
      count_q   <= 32'd0;
      expired_q <= 1'b0;
    end else begin
      aw_held_q <= aw_held_d;
      aw_addr_q <= aw_addr_d;
      w_held_q  <= w_held_d;
      w_data_q  <= w_data_d;
      w_strb_q  <= w_strb_d;
      bvalid_q  <= bvalid_d;
      bresp_q   <= bresp_d;
      rvalid_q  <= rvalid_d;
      rresp_q   <= rresp_d;
      rdata_q   <= rdata_d;
      en_q      <= en_d;
      ie_q      <= ie_d;
      mode_q    <= mode_d;
      load_q    <= load_d;
      count_q   <= count_d;
      expired_q <= expired_d;
    end
  end

`ifdef FORMAL
  // Design-intent properties (not run).
  reg f_past_valid = 1'b0;
  reg f_reset_seen = 1'b0;
  always @(posedge aclk) begin
    f_past_valid <= 1'b1;
    if (!aresetn) f_reset_seen <= 1'b1;
  end

  always @(*) begin
    if (f_reset_seen) begin
      assert (!(aw_held_q && w_held_q));
      assert (!(bvalid_q && (aw_held_q || w_held_q)));
      assert ((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
      assert ((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
    end
  end

  always @(posedge aclk) begin
    if (f_past_valid && f_reset_seen && $past(f_reset_seen) && $past(aresetn)) begin
      if ($past(bvalid_q) && !$past(s_axil_bready))
        assert (bvalid_q && (bresp_q == $past(bresp_q)));
      if ($past(rvalid_q) && !$past(s_axil_rready))
        assert (rvalid_q && (rresp_q == $past(rresp_q)) && (rdata_q == $past(rdata_q)));
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
