// Self-checking testbench for axil_timer.
// Each core: a per-cycle reference model (written from the interface spec)
// plus directed, edge-timed checks. TMR-LOAD-END-EDGE: both readings accepted.
module axil_timer_tb_core #(
    parameter integer AW = 4
);

  localparam integer TMO = 200;
  localparam [1:0] OK  = 2'b00;
  localparam [1:0] ERR = 2'b10;
  localparam [3:0] SF  = 4'hF;

  reg clk = 1'b0;
  always #5 clk = ~clk;

  integer cyc = 0;
  always @(posedge clk) cyc <= cyc + 1;

  reg          rstn;
  reg [AW-1:0] awaddr;
  reg          awvalid;
  reg [31:0]   wdata;
  reg [3:0]    wstrb;
  reg          wvalid;
  reg          bready;
  reg [AW-1:0] araddr;
  reg          arvalid;
  reg          rready;
  wire         awready, wready, bvalid, arready, rvalid, irq;
  wire [1:0]   bresp, rresp;
  wire [31:0]  rdata;

  axil_timer #(.ADDR_WIDTH(AW)) dut (
      .aclk          (clk),
      .aresetn       (rstn),
      .s_axil_awaddr (awaddr),
      .s_axil_awvalid(awvalid),
      .s_axil_awready(awready),
      .s_axil_wdata  (wdata),
      .s_axil_wstrb  (wstrb),
      .s_axil_wvalid (wvalid),
      .s_axil_wready (wready),
      .s_axil_bresp  (bresp),
      .s_axil_bvalid (bvalid),
      .s_axil_bready (bready),
      .s_axil_araddr (araddr),
      .s_axil_arvalid(arvalid),
      .s_axil_arready(arready),
      .s_axil_rdata  (rdata),
      .s_axil_rresp  (rresp),
      .s_axil_rvalid (rvalid),
      .s_axil_rready (rready),
      .irq           (irq)
  );

  integer passed = 0;
  integer failed = 0;
  integer cmp_passed = 0;
  integer cmp_failed = 0;
  reg     done = 1'b0;
  reg     chk_en = 1'b0;
  integer last_wedge;

  // ------------------------------------------------------------ reference model
  reg          m_alive  [0:1];
  reg          m_kill   [0:1];
  reg          m_awheld [0:1];
  reg [AW-1:0] m_awaddr [0:1];
  reg          m_wheld  [0:1];
  reg [31:0]   m_wdata  [0:1];
  reg [3:0]    m_wstrb  [0:1];
  reg          m_bvalid [0:1];
  reg [1:0]    m_bresp  [0:1];
  reg          m_rvalid [0:1];
  reg [1:0]    m_rresp  [0:1];
  reg [31:0]   m_rdata  [0:1];
  reg          m_en     [0:1];
  reg          m_ie     [0:1];
  reg          m_mode   [0:1];
  reg          m_exp    [0:1];
  reg [31:0]   m_load   [0:1];
  reg [31:0]   m_count  [0:1];

  integer      mk;
  reg          t_awf, t_wf, t_arf, t_done, t_map, t_rmap, t_ctrl, t_ldw, t_stclr, t_cend;
  reg          t_en_n, t_exp_n;
  reg [AW-1:0] t_addr;
  reg [31:0]   t_data, t_lnew, t_rval, t_cnext;
  reg [3:0]    t_strb;
  reg [1:0]    t_idx;

  always @(posedge clk) begin
    for (mk = 0; mk < 2; mk = mk + 1) begin
      if (!rstn) begin
        m_alive[mk]  = 1'b1;
        m_awheld[mk] = 1'b0;
        m_awaddr[mk] = {AW{1'b0}};
        m_wheld[mk]  = 1'b0;
        m_wdata[mk]  = 32'd0;
        m_wstrb[mk]  = 4'd0;
        m_bvalid[mk] = 1'b0;
        m_bresp[mk]  = 2'b00;
        m_rvalid[mk] = 1'b0;
        m_rresp[mk]  = 2'b00;
        m_rdata[mk]  = 32'd0;
        m_en[mk]     = 1'b0;
        m_ie[mk]     = 1'b0;
        m_mode[mk]   = 1'b0;
        m_exp[mk]    = 1'b0;
        m_load[mk]   = 32'd0;
        m_count[mk]  = 32'd0;
      end else begin
        if (m_kill[mk] === 1'b1) m_alive[mk] = 1'b0;
        t_awf  = awvalid && !m_awheld[mk] && !m_bvalid[mk];
        t_wf   = wvalid && !m_wheld[mk] && !m_bvalid[mk];
        t_arf  = arvalid && !m_rvalid[mk];
        t_done = (t_awf || m_awheld[mk]) && (t_wf || m_wheld[mk]);
        t_addr = m_awheld[mk] ? m_awaddr[mk] : awaddr;
        t_data = m_wheld[mk] ? m_wdata[mk] : wdata;
        t_strb = m_wheld[mk] ? m_wstrb[mk] : wstrb;
        t_map  = (t_addr[1:0] == 2'b00) && ((t_addr >> 4) == {AW{1'b0}});
        t_idx  = t_addr[3:2];
        t_ctrl  = t_done && t_map && (t_idx == 2'd0) && t_strb[0];
        t_ldw   = t_done && t_map && (t_idx == 2'd1);
        t_stclr = t_done && t_map && (t_idx == 2'd3) && t_strb[0] && t_data[0];
        t_cend  = m_en[mk] && ((m_count[mk] == 32'd0) || (m_count[mk] == 32'd1));
        t_lnew = m_load[mk];
        if (t_ldw) begin
          if (t_strb[0]) t_lnew[7:0]   = t_data[7:0];
          if (t_strb[1]) t_lnew[15:8]  = t_data[15:8];
          if (t_strb[2]) t_lnew[23:16] = t_data[23:16];
          if (t_strb[3]) t_lnew[31:24] = t_data[31:24];
        end
        t_rmap = (araddr[1:0] == 2'b00) && ((araddr >> 4) == {AW{1'b0}});
        case (araddr[3:2])
          2'd0:    t_rval = {29'd0, m_mode[mk], m_ie[mk], m_en[mk]};
          2'd1:    t_rval = m_load[mk];
          2'd2:    t_rval = m_count[mk];
          default: t_rval = {31'd0, m_exp[mk]};
        endcase
        if (!t_rmap) t_rval = 32'd0;
        if (t_ctrl) t_en_n = t_data[0];
        else if (t_cend && !m_mode[mk]) t_en_n = 1'b0;
        else t_en_n = m_en[mk];
        if (t_ctrl && t_data[0]) t_cnext = m_load[mk];
        else if (t_cend) t_cnext = m_mode[mk] ? ((mk == 0) ? m_load[mk] : t_lnew) : 32'd0;
        else if (m_en[mk]) t_cnext = m_count[mk] - 32'd1;
        else t_cnext = m_count[mk];
        if (t_cend) t_exp_n = 1'b1;
        else if (t_stclr) t_exp_n = 1'b0;
        else t_exp_n = m_exp[mk];

        if (t_arf) begin
          m_rvalid[mk] = 1'b1;
          m_rdata[mk]  = t_rval;
          m_rresp[mk]  = t_rmap ? 2'b00 : 2'b10;
        end else if (m_rvalid[mk] && rready) begin
          m_rvalid[mk] = 1'b0;
        end
        if (t_done) begin
          m_bvalid[mk] = 1'b1;
          m_bresp[mk]  = (!t_map || (t_idx == 2'd2)) ? 2'b10 : 2'b00;
        end else if (m_bvalid[mk] && bready) begin
          m_bvalid[mk] = 1'b0;
        end
        if (t_done) begin
          m_awheld[mk] = 1'b0;
          m_wheld[mk]  = 1'b0;
        end else begin
          if (t_awf) begin
            m_awheld[mk] = 1'b1;
            m_awaddr[mk] = awaddr;
          end
          if (t_wf) begin
            m_wheld[mk] = 1'b1;
            m_wdata[mk] = wdata;
            m_wstrb[mk] = wstrb;
          end
        end
        if (t_ctrl) begin
          m_ie[mk]   = t_data[1];
          m_mode[mk] = t_data[2];
        end
        m_en[mk]    = t_en_n;
        m_count[mk] = t_cnext;
        m_exp[mk]   = t_exp_n;
        m_load[mk]  = t_lnew;
      end
    end
  end

  // ------------------------------------------------------------ comparator
  integer mj;
  reg     mt [0:1];
  reg     any_m;
  always @(negedge clk) begin
    if (chk_en) begin
      any_m = 1'b0;
      for (mj = 0; mj < 2; mj = mj + 1) begin
        mt[mj] = (m_alive[mj] === 1'b1) &&
                 (awready === (!m_awheld[mj] && !m_bvalid[mj])) &&
                 (wready  === (!m_wheld[mj] && !m_bvalid[mj])) &&
                 (arready === !m_rvalid[mj]) &&
                 (bvalid  === m_bvalid[mj]) &&
                 (!m_bvalid[mj] || (bresp === m_bresp[mj])) &&
                 (rvalid  === m_rvalid[mj]) &&
                 (!m_rvalid[mj] || ((rresp === m_rresp[mj]) && (rdata === m_rdata[mj]))) &&
                 (irq === (m_exp[mj] && m_ie[mj]));
        if (mt[mj]) any_m = 1'b1;
      end
      if (any_m) begin
        cmp_passed = cmp_passed + 1;
        for (mj = 0; mj < 2; mj = mj + 1) m_kill[mj] = (m_alive[mj] === 1'b1) && !mt[mj];
      end else begin
        cmp_failed = cmp_failed + 1;
        for (mj = 0; mj < 2; mj = mj + 1) m_kill[mj] = 1'b0;
        $error("[AW=%0d] edge %0d: DUT differs from model: awready=%b wready=%b arready=%b bvalid=%b bresp=%b rvalid=%b rresp=%b rdata=%h irq=%b | model0: bvalid=%b bresp=%b rvalid=%b rresp=%b rdata=%h irq=%b count=%h",
               AW, cyc, awready, wready, arready, bvalid, bresp, rvalid, rresp, rdata, irq,
               m_bvalid[0], m_bresp[0], m_rvalid[0], m_rresp[0], m_rdata[0], m_exp[0] && m_ie[0], m_count[0]);
      end
    end else begin
      m_kill[0] = 1'b0;
      m_kill[1] = 1'b0;
    end
  end

  // ------------------------------------------------------------ helpers
  function [AW-1:0] ad;
    input integer v;
    begin
      ad = v[AW-1:0];
    end
  endfunction

  task automatic tick;
    begin
      @(posedge clk);
      #1;
    end
  endtask

  task automatic check(input c, input [8*96-1:0] what);
    begin
      if (c === 1'b1) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("[AW=%0d] edge %0d: check failed: %0s", AW, cyc, what);
      end
    end
  endtask

  task automatic check32(input [31:0] got, input [31:0] exp, input [8*96-1:0] what);
    begin
      if (got === exp) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("[AW=%0d] edge %0d: %0s: got 0x%08h, expected 0x%08h", AW, cyc, what, got, exp);
      end
    end
  endtask

  task automatic check_either(input [31:0] got, input [31:0] e0, input [31:0] e1, input [8*96-1:0] what);
    begin
      if ((got === e0) || (got === e1)) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("[AW=%0d] edge %0d: %0s: got 0x%08h, expected 0x%08h or 0x%08h", AW, cyc, what, got, e0, e1);
      end
    end
  endtask

  task automatic wait_aw;
    integer n;
    reg acc;
    begin
      acc = 1'b0; n = 0;
      while (!acc && n < TMO) begin
        acc = awready;
        tick;
        n = n + 1;
      end
      awvalid = 1'b0;
      if (!acc) check(1'b0, "AW not accepted (timeout)");
    end
  endtask

  task automatic wait_w;
    integer n;
    reg acc;
    begin
      acc = 1'b0; n = 0;
      while (!acc && n < TMO) begin
        acc = wready;
        tick;
        n = n + 1;
      end
      wvalid = 1'b0;
      if (!acc) check(1'b0, "W not accepted (timeout)");
    end
  endtask

  task automatic wait_ar;
    integer n;
    reg acc;
    begin
      acc = 1'b0; n = 0;
      while (!acc && n < TMO) begin
        acc = arready;
        tick;
        n = n + 1;
      end
      arvalid = 1'b0;
      if (!acc) check(1'b0, "AR not accepted (timeout)");
    end
  endtask

  task automatic wait_aw_w;
    integer n;
    reg acc_aw, acc_w, got_aw, got_w;
    begin
      got_aw = !awvalid; got_w = !wvalid; n = 0;
      while (!(got_aw && got_w) && n < TMO) begin
        acc_aw = awvalid && awready;
        acc_w  = wvalid && wready;
        tick;
        n = n + 1;
        if (acc_aw) begin awvalid = 1'b0; got_aw = 1'b1; end
        if (acc_w)  begin wvalid  = 1'b0; got_w  = 1'b1; end
      end
      if (!(got_aw && got_w)) check(1'b0, "AW/W not accepted (timeout)");
    end
  endtask

  task automatic wait_b(output [1:0] resp);
    integer n;
    reg acc;
    begin
      acc = 1'b0; n = 0; resp = 2'b11;
      while (!acc && n < TMO) begin
        acc = bvalid && bready;
        if (bvalid) resp = bresp;
        tick;
        n = n + 1;
      end
      if (!acc) check(1'b0, "B not received (timeout)");
    end
  endtask

  task automatic wait_r(output [31:0] data, output [1:0] resp);
    integer n;
    reg acc;
    begin
      acc = 1'b0; n = 0; resp = 2'b11; data = 32'd0;
      while (!acc && n < TMO) begin
        acc = rvalid && rready;
        if (rvalid) begin data = rdata; resp = rresp; end
        tick;
        n = n + 1;
      end
      if (!acc) check(1'b0, "R not received (timeout)");
    end
  endtask

  // order: 0 AW and W together, 1 AW first, 2 W first
  task automatic do_write(input [AW-1:0] a, input [31:0] d, input [3:0] s,
                          input integer order, input integer gap, input integer bstall,
                          output [1:0] resp, output integer e);
    begin
      awaddr = a; wdata = d; wstrb = s;
      bready = (bstall == 0);
      if (order == 1) begin
        awvalid = 1'b1; wait_aw;
        repeat (gap) tick;
        wvalid = 1'b1; wait_w;
      end else if (order == 2) begin
        wvalid = 1'b1; wait_w;
        repeat (gap) tick;
        awvalid = 1'b1; wait_aw;
      end else begin
        awvalid = 1'b1; wvalid = 1'b1; wait_aw_w;
      end
      e = cyc;
      if (bstall > 0) begin
        check(bvalid, "bvalid high after completing edge");
        repeat (bstall) begin
          check(bvalid && !awready && !wready, "B held and AW/W blocked during B stall");
          tick;
        end
        bready = 1'b1;
      end
      wait_b(resp);
    end
  endtask

  task automatic wr(input [AW-1:0] a, input [31:0] d, input [3:0] s, input [1:0] exp_resp);
    reg [1:0] r;
    integer e;
    begin
      do_write(a, d, s, 0, 0, 0, r, e);
      last_wedge = e;
      check32({30'd0, r}, {30'd0, exp_resp}, "write response");
    end
  endtask

  task automatic do_read(input [AW-1:0] a, input integer rstall,
                         output [31:0] data, output [1:0] resp, output integer e);
    begin
      araddr = a;
      rready = (rstall == 0);
      arvalid = 1'b1;
      wait_ar;
      e = cyc;
      if (rstall > 0) begin
        check(rvalid, "rvalid high after accepting edge");
        repeat (rstall) begin
          check(rvalid && !arready, "R held and AR blocked during R stall");
          tick;
        end
        rready = 1'b1;
      end
      wait_r(data, resp);
    end
  endtask

  task automatic rd(input [AW-1:0] a, input [31:0] exp_d, input [1:0] exp_r);
    reg [31:0] d;
    reg [1:0] r;
    integer e;
    begin
      do_read(a, 0, d, r, e);
      check32(d, exp_d, "read data");
      check32({30'd0, r}, {30'd0, exp_r}, "read response");
    end
  endtask

  // AW sent first and held; W lands so the write completes exactly on 'target'
  task automatic write_at_edge(input [AW-1:0] a, input [31:0] d, input [3:0] s, input integer target);
    reg [1:0] r;
    begin
      awaddr = a; wdata = d; wstrb = s; bready = 1'b1;
      awvalid = 1'b1;
      wait_aw;
      if (cyc > target - 1) check(1'b0, "write_at_edge: target edge already passed");
      while (cyc < target - 1) tick;
      check(wready, "wready high while AW held");
      wvalid = 1'b1;
      tick;
      wvalid = 1'b0;
      check(cyc == target, "write completed on the target edge");
      wait_b(r);
      check32({30'd0, r}, {30'd0, OK}, "write_at_edge response");
    end
  endtask

  task automatic expect_irq_at(input integer target);
    begin
      if (cyc >= target) check(1'b0, "expect_irq_at: target edge already passed");
      while (cyc < target) begin
        check(irq == 1'b0, "irq low before the count-end edge");
        tick;
      end
      check(irq == 1'b1, "irq high after the count-end edge");
    end
  endtask

  // ------------------------------------------------------------ stimulus
  integer    te, te2, ta, tk;
  reg [31:0] td;
  reg [1:0]  tr;

  initial begin
    rstn = 1'b0;
    awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0; bready = 1'b0; rready = 1'b0;
    awaddr = {AW{1'b0}}; araddr = {AW{1'b0}}; wdata = 32'd0; wstrb = 4'd0;
    last_wedge = 0;
    repeat (3) @(posedge clk);
    #1;
    rstn = 1'b1;
    chk_en = 1'b1;

    // ---- reset values (TMR-RESET, TMR-MAP)
    check(awready && wready && arready, "readies high after reset");
    check(!bvalid && !rvalid && !irq, "bvalid, rvalid and irq low after reset");
    rd(ad(0), 32'd0, OK);
    rd(ad(4), 32'd0, OK);
    rd(ad(8), 32'd0, OK);
    rd(ad(12), 32'd0, OK);

    // ---- LOAD strobes (TMR-LOAD)
    wr(ad(4), 32'hAABBCCDD, SF, OK);       rd(ad(4), 32'hAABBCCDD, OK);
    wr(ad(4), 32'h11223344, 4'b0101, OK);  rd(ad(4), 32'hAA22CC44, OK);
    wr(ad(4), 32'h55667788, 4'b1010, OK);  rd(ad(4), 32'h55227744, OK);
    wr(ad(4), 32'hFFFFFFFF, 4'b0000, OK);  rd(ad(4), 32'h55227744, OK);

    // ---- CTRL strobes (TMR-CTRL-STRB)
    wr(ad(0), 32'h00000006, 4'b1110, OK);  rd(ad(0), 32'd0, OK);
    wr(ad(0), 32'hFFFFFFF6, 4'b0001, OK);  rd(ad(0), 32'h00000006, OK);
    wr(ad(0), 32'd0, SF, OK);              rd(ad(0), 32'd0, OK);
    wr(ad(12), 32'hFFFFFFFF, 4'b1110, OK); rd(ad(12), 32'd0, OK);

    // ---- errors and decode (TMR-SLVERR, TMR-DECODE)
    wr(ad(8), 32'h12345678, SF, ERR);      rd(ad(8), 32'd0, OK);
    wr(ad(8), 32'h00000001, 4'b0000, ERR);
    wr(ad(5), 32'h00000001, SF, ERR);
    wr(ad(6), 32'h00000001, SF, ERR);
    wr(ad(7), 32'h00000001, SF, ERR);
    wr(ad(1), 32'h00000001, SF, ERR);
    rd(ad(4), 32'h55227744, OK);
    rd(ad(0), 32'd0, OK);
    rd(ad(1), 32'd0, ERR);
    rd(ad(2), 32'd0, ERR);
    rd(ad(3), 32'd0, ERR);
    rd(ad(13), 32'd0, ERR);
    if (AW > 4) begin
      wr(ad(16), 32'h00000001, SF, ERR);
      wr(ad(20), 32'h00000000, SF, ERR);
      wr(ad(28), 32'h00000001, SF, ERR);
      wr(ad((1 << AW) - 4), 32'h00000007, SF, ERR);
      rd(ad(0), 32'd0, OK);
      rd(ad(4), 32'h55227744, OK);
      rd(ad(12), 32'd0, OK);
      rd(ad(16), 32'd0, ERR);
      rd(ad(20), 32'd0, ERR);
      rd(ad(24), 32'd0, ERR);
      rd(ad(28), 32'd0, ERR);
      rd(ad((1 << AW) - 4), 32'd0, ERR);
    end

    // ---- AW/W ordering (TMR-ORDER)
    do_write(ad(4), 32'h01020304, SF, 1, 3, 0, tr, te); check32({30'd0, tr}, {30'd0, OK}, "AW first, gap 3");
    rd(ad(4), 32'h01020304, OK);
    do_write(ad(4), 32'h0A0B0C0D, SF, 2, 2, 0, tr, te); check32({30'd0, tr}, {30'd0, OK}, "W first, gap 2");
    rd(ad(4), 32'h0A0B0C0D, OK);
    do_write(ad(4), 32'h10203040, SF, 1, 0, 0, tr, te); check32({30'd0, tr}, {30'd0, OK}, "AW first, gap 0");
    rd(ad(4), 32'h10203040, OK);
    do_write(ad(8), 32'h00000001, SF, 1, 2, 0, tr, te); check32({30'd0, tr}, {30'd0, ERR}, "split COUNT write");
    do_write(ad(1), 32'h00000001, SF, 2, 1, 0, tr, te); check32({30'd0, tr}, {30'd0, ERR}, "split unmapped write");
    do_write(ad(4), 32'h50607080, SF, 2, 0, 0, tr, te); check32({30'd0, tr}, {30'd0, OK}, "W first, gap 0");
    rd(ad(4), 32'h50607080, OK);

    // ---- read completes while a write address is held
    awaddr = ad(4); wdata = 32'hCAFEF00D; wstrb = SF; bready = 1'b1;
    awvalid = 1'b1; wait_aw;
    rd(ad(4), 32'h50607080, OK);
    wvalid = 1'b1; wait_w; wait_b(tr);
    check32({30'd0, tr}, {30'd0, OK}, "held-AW write response");
    rd(ad(4), 32'hCAFEF00D, OK);

    // ---- read and write accepted on the same edge (TMR-READ-VALUE)
    check(awready && wready && arready, "all readies high when idle");
    awaddr = ad(4); wdata = 32'h66666666; wstrb = SF; araddr = ad(4);
    bready = 1'b1; rready = 1'b1;
    awvalid = 1'b1; wvalid = 1'b1; arvalid = 1'b1;
    tick;
    awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
    check(bvalid && rvalid, "B and R valid after same-edge write and read");
    check32(rdata, 32'hCAFEF00D, "same-edge read returns the pre-edge LOAD");
    check((bresp == OK) && (rresp == OK), "same-edge responses OKAY");
    tick;
    check(!bvalid && !rvalid, "B and R consumed");
    rd(ad(4), 32'h66666666, OK);

    // ---- back-pressure on B (TMR-READY-HELD-REQUEST, TMR-RESPONSE)
    do_write(ad(4), 32'h77777777, SF, 0, 0, 5, tr, te);
    check32({30'd0, tr}, {30'd0, OK}, "stalled B response");
    awaddr = ad(4); wdata = 32'h12121212; wstrb = SF; bready = 1'b0;
    awvalid = 1'b1; wvalid = 1'b1; wait_aw_w;
    awaddr = ad(4); wdata = 32'h34343434; awvalid = 1'b1; wvalid = 1'b1;
    repeat (4) begin
      check(!awready && !wready && bvalid, "new write blocked while B waits");
      tick;
    end
    bready = 1'b1;
    wait_aw_w;
    wait_b(tr);
    check32({30'd0, tr}, {30'd0, OK}, "second write response");
    rd(ad(4), 32'h34343434, OK);

    // ---- back-pressure on R
    araddr = ad(4); rready = 1'b0; arvalid = 1'b1; wait_ar;
    araddr = ad(0); arvalid = 1'b1;
    repeat (5) begin
      check(rvalid && !arready, "new read blocked while R waits");
      check32(rdata, 32'h34343434, "rdata stable while R stalled");
      tick;
    end
    rready = 1'b1;
    wait_ar;
    wait_r(td, tr);
    check32(td, 32'd0, "read after R stall returns CTRL");

    // ---- one-shot (TMR-START, TMR-COUNT-LENGTH, TMR-ONESHOT, TMR-IRQ)
    wr(ad(12), 32'h1, SF, OK);
    wr(ad(4), 32'd5, SF, OK);
    wr(ad(0), 32'h3, SF, OK); te = last_wedge;
    expect_irq_at(te + 5);
    rd(ad(0), 32'h2, OK);
    rd(ad(8), 32'd0, OK);
    rd(ad(12), 32'h1, OK);
    repeat (6) begin check(irq, "irq held until cleared"); tick; end
    wr(ad(12), 32'h0, SF, OK);       check(irq, "STATUS write of 0 clears nothing");
    wr(ad(12), 32'h1, 4'b1110, OK);  check(irq, "STATUS write without wstrb[0] clears nothing");
    wr(ad(12), 32'h1, SF, OK);       check(!irq, "irq low after STATUS clear");
    repeat (12) begin check(!irq, "no second interrupt in one-shot"); tick; end
    rd(ad(12), 32'd0, OK);

    // ---- IE masks irq only (TMR-IRQ, TMR-IRQ-EDGE)
    wr(ad(4), 32'd3, SF, OK);
    wr(ad(0), 32'h1, SF, OK); te = last_wedge;
    while (cyc < te + 6) begin check(!irq, "irq masked while IE is 0"); tick; end
    rd(ad(12), 32'h1, OK);
    rd(ad(0), 32'h0, OK);
    wr(ad(0), 32'h2, SF, OK);  check(irq, "writing IE 1 while EXPIRED set raises irq");
    rd(ad(8), 32'd0, OK);
    wr(ad(0), 32'h0, SF, OK);  check(!irq, "writing IE 0 lowers irq");
    wr(ad(0), 32'h2, SF, OK);  check(irq, "irq high again with IE 1");
    wr(ad(12), 32'h1, SF, OK); check(!irq, "STATUS clear lowers irq");
    wr(ad(0), 32'h0, SF, OK);

    // ---- COUNT while counting, stop (TMR-COUNT-READ, TMR-STOP, TMR-STOP-EDGE)
    wr(ad(4), 32'd40, SF, OK);
    wr(ad(0), 32'h1, SF, OK); te = last_wedge;
    do_read(ad(8), 0, td, tr, ta); check32(td, 40 - (ta - 1 - te), "COUNT while counting");
    do_read(ad(8), 0, td, tr, ta); check32(td, 40 - (ta - 1 - te), "COUNT while counting");
    do_read(ad(8), 6, td, tr, ta); check32(td, 40 - (ta - 1 - te), "COUNT with stalled R");
    rd(ad(0), 32'h1, OK);
    wr(ad(0), 32'h0, SF, OK); te2 = last_wedge;
    check((te2 - te) < 40, "stop lands before the count end");
    rd(ad(8), 40 - (te2 - te), OK);
    repeat (5) tick;
    rd(ad(8), 40 - (te2 - te), OK);
    rd(ad(0), 32'd0, OK);
    rd(ad(12), 32'd0, OK);
    wr(ad(0), 32'h0, SF, OK);
    rd(ad(8), 40 - (te2 - te), OK);

    // ---- restart with mode change (TMR-START, TMR-RESTART-MODE, TMR-PERIODIC)
    wr(ad(4), 32'd30, SF, OK);
    wr(ad(0), 32'h1, SF, OK);
    repeat (4) tick;
    wr(ad(0), 32'h7, SF, OK); te2 = last_wedge;
    do_read(ad(8), 0, td, tr, ta); check32(td, 30 - (ta - 1 - te2), "COUNT after restart");
    expect_irq_at(te2 + 30);
    wr(ad(12), 32'h1, SF, OK); check(!irq, "irq low after clear (periodic)");
    expect_irq_at(te2 + 60);
    rd(ad(0), 32'h7, OK);
    wr(ad(0), 32'h0, SF, OK);
    wr(ad(12), 32'h1, SF, OK);

    // ---- periodic with LOAD change mid-period
    wr(ad(4), 32'd12, SF, OK);
    wr(ad(0), 32'h7, SF, OK); te = last_wedge;
    expect_irq_at(te + 12);
    wr(ad(12), 32'h1, SF, OK);
    wr(ad(4), 32'd7, SF, OK);
    check(last_wedge < te + 24, "LOAD write lands inside the second period");
    expect_irq_at(te + 24);
    wr(ad(12), 32'h1, SF, OK);
    expect_irq_at(te + 31);
    wr(ad(12), 32'h1, SF, OK);
    expect_irq_at(te + 38);
    wr(ad(0), 32'h0, SF, OK);
    wr(ad(12), 32'h1, SF, OK);

    // ---- periodic continues with EXPIRED left set (TMR-PERIODIC-EXPIRED-SET)
    wr(ad(4), 32'd6, SF, OK);
    wr(ad(0), 32'h5, SF, OK); te = last_wedge;
    repeat (3) begin
      repeat (7) tick;
      do_read(ad(8), 0, td, tr, ta);
      tk = (ta - 1 - te) % 6;
      check32(td, 6 - tk, "periodic COUNT with EXPIRED left set");
    end
    rd(ad(12), 32'h1, OK);
    rd(ad(0), 32'h5, OK);
    wr(ad(0), 32'h0, SF, OK);
    wr(ad(12), 32'h1, SF, OK);

    // ---- LOAD 0 (TMR-LOAD-ZERO, TMR-LOAD-ZERO-PERIODIC, TMR-END-BEATS-CLEAR)
    wr(ad(4), 32'd0, SF, OK);
    wr(ad(0), 32'h3, SF, OK); te = last_wedge;
    check(cyc == te + 1, "returned one edge after LOAD-0 start");
    check(irq, "LOAD 0 one-shot ends on the next edge");
    rd(ad(0), 32'h2, OK);
    rd(ad(8), 32'd0, OK);
    wr(ad(12), 32'h1, SF, OK); check(!irq, "clear after LOAD-0 one-shot");
    wr(ad(0), 32'h7, SF, OK);
    check(irq, "LOAD 0 periodic ends on every edge");
    rd(ad(8), 32'd0, OK);
    rd(ad(0), 32'h7, OK);
    wr(ad(12), 32'h1, SF, OK); check(irq, "clear loses to count end (LOAD 0 periodic)");
    rd(ad(12), 32'h1, OK);
    wr(ad(0), 32'h0, SF, OK);
    rd(ad(8), 32'd0, OK);
    wr(ad(12), 32'h1, SF, OK);
    rd(ad(12), 32'd0, OK);

    // ---- full 32-bit count (TMR-COUNT-32BIT)
    wr(ad(4), 32'h80000001, SF, OK);
    wr(ad(0), 32'h1, SF, OK); te = last_wedge;
    do_read(ad(8), 0, td, tr, ta); check32(td, 32'h80000001 - (ta - 1 - te), "32-bit COUNT, high bit set");
    rd(ad(0), 32'h1, OK);
    rd(ad(12), 32'd0, OK);
    wr(ad(4), 32'hFFFFFFFF, SF, OK);
    wr(ad(0), 32'h1, SF, OK); te = last_wedge;
    do_read(ad(8), 0, td, tr, ta); check32(td, 32'hFFFFFFFF - (ta - 1 - te), "32-bit COUNT from all ones");
    wr(ad(4), 32'h00010000, SF, OK);
    wr(ad(0), 32'h1, SF, OK); te = last_wedge;
    do_read(ad(8), 0, td, tr, ta); check32(td, 32'h00010000 - (ta - 1 - te), "COUNT borrow through bit 16");
    wr(ad(0), 32'h0, SF, OK);
    rd(ad(12), 32'd0, OK);

    // ---- CTRL write on the count-end edge (TMR-CTRL-WINS)
    wr(ad(4), 32'd10, SF, OK);
    wr(ad(0), 32'h5, SF, OK); te = last_wedge;
    write_at_edge(ad(0), 32'h4, SF, te + 10);
    rd(ad(0), 32'h4, OK);
    rd(ad(8), 32'd10, OK);
    repeat (5) tick;
    rd(ad(8), 32'd10, OK);
    rd(ad(12), 32'h1, OK);
    wr(ad(12), 32'h1, SF, OK);

    wr(ad(0), 32'h1, SF, OK); te = last_wedge;
    write_at_edge(ad(0), 32'h4, SF, te + 10);
    rd(ad(8), 32'd0, OK);
    rd(ad(0), 32'h4, OK);
    rd(ad(12), 32'h1, OK);
    wr(ad(12), 32'h1, SF, OK);

    wr(ad(0), 32'h1, SF, OK); te = last_wedge;
    write_at_edge(ad(0), 32'h1, SF, te + 10);
    do_read(ad(8), 0, td, tr, ta); check32(td, 10 - (ta - 1 - (te + 10)), "restart on count-end edge reloads COUNT");
    rd(ad(12), 32'h1, OK);
    rd(ad(0), 32'h1, OK);
    wr(ad(12), 32'h1, SF, OK);
    while (cyc < te + 21) tick;
    rd(ad(12), 32'h1, OK);
    rd(ad(0), 32'h0, OK);
    rd(ad(8), 32'd0, OK);
    wr(ad(12), 32'h1, SF, OK);

    // ---- STATUS clear on the count-end edge (TMR-END-BEATS-CLEAR)
    wr(ad(0), 32'h7, SF, OK); te = last_wedge;
    expect_irq_at(te + 10);
    write_at_edge(ad(12), 32'h1, SF, te + 20);
    check(irq, "STATUS clear on count-end edge: EXPIRED stays set");
    rd(ad(12), 32'h1, OK);
    wr(ad(12), 32'h1, SF, OK); check(!irq, "clear off the count-end edge works");
    wr(ad(0), 32'h0, SF, OK);
    wr(ad(0), 32'h3, SF, OK); te = last_wedge;
    write_at_edge(ad(12), 32'h1, SF, te + 10);
    check(irq, "one-shot end beats a same-edge clear");
    rd(ad(12), 32'h1, OK);
    wr(ad(12), 32'h1, SF, OK);
    wr(ad(0), 32'h0, SF, OK);

    // ---- LOAD write on a periodic count-end edge (TMR-LOAD-END-EDGE, both accepted)
    wr(ad(4), 32'd8, SF, OK);
    wr(ad(0), 32'h5, SF, OK); te = last_wedge;
    write_at_edge(ad(4), 32'd4, SF, te + 8);
    do_read(ad(8), 0, td, tr, ta);
    tk = ta - 1 - (te + 8);
    check_either(td, 8 - tk, 4 - tk, "COUNT after LOAD write on periodic count-end edge");
    rd(ad(4), 32'd4, OK);
    while (cyc < te + 20) tick;
    do_read(ad(8), 0, td, tr, ta);
    check32(td, 4 - ((ta - 1 - te - 16) % 4), "periods after the end-edge LOAD use the new LOAD");
    wr(ad(0), 32'h0, SF, OK);
    wr(ad(12), 32'h1, SF, OK);

    // ---- reset during traffic (TMR-RESET, TMR-RESET-EDGE)
    wr(ad(4), 32'd5, SF, OK);
    wr(ad(0), 32'h7, SF, OK); te = last_wedge;
    expect_irq_at(te + 5);
    awaddr = ad(4); wdata = 32'h00000099; wstrb = SF; bready = 1'b0;
    awvalid = 1'b1; wvalid = 1'b1; wait_aw_w;
    araddr = ad(4); rready = 1'b0; arvalid = 1'b1; wait_ar;
    check(bvalid && rvalid && irq, "B and R pending and irq high before reset");
    rstn = 1'b0;
    tick;
    rstn = 1'b1;
    check(awready && wready && arready, "readies high after reset during traffic");
    check(!bvalid && !rvalid && !irq, "no response kept and irq low after reset");
    bready = 1'b1; rready = 1'b1;
    rd(ad(0), 32'd0, OK);
    rd(ad(4), 32'd0, OK);
    rd(ad(8), 32'd0, OK);
    rd(ad(12), 32'd0, OK);
    repeat (8) begin check(!irq, "timer stopped after reset"); tick; end

    awaddr = ad(4); wdata = 32'hDEADDEAD; wstrb = SF; awvalid = 1'b1; wait_aw;
    rstn = 1'b0;
    tick;
    rstn = 1'b1;
    check(awready && wready, "no address held after reset");
    wdata = 32'hABCD0123; wstrb = SF; wvalid = 1'b1; wait_w;
    repeat (3) begin
      check(!bvalid && !wready && awready, "W alone is held, no B without an address");
      tick;
    end
    awaddr = ad(4); awvalid = 1'b1; wait_aw;
    wait_b(tr);
    check32({30'd0, tr}, {30'd0, OK}, "write completes after AW arrives");
    rd(ad(4), 32'hABCD0123, OK);

    repeat (3) tick;
    done = 1'b1;
  end

endmodule

module tb_axil_timer;

  axil_timer_tb_core #(.AW(4)) u_aw4 ();
  axil_timer_tb_core #(.AW(6)) u_aw6 ();
  axil_timer_tb_core #(.AW(8)) u_aw8 ();

  reg [8*64-1:0] nonce;
  integer total_passed;
  integer total_failed;
  integer wd_passed;
  integer wd_failed;

  initial begin
    nonce = "unset";
    if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = "unset";
    wait (u_aw4.done && u_aw6.done && u_aw8.done);
    #1;
    total_passed = u_aw4.passed + u_aw4.cmp_passed + u_aw6.passed + u_aw6.cmp_passed
                 + u_aw8.passed + u_aw8.cmp_passed;
    total_failed = u_aw4.failed + u_aw4.cmp_failed + u_aw6.failed + u_aw6.cmp_failed
                 + u_aw8.failed + u_aw8.cmp_failed;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, total_passed, total_failed);
    $finish;
  end

  initial begin
    #2000000;
    $error("watchdog: simulation did not finish in time");
    wd_passed = u_aw4.passed + u_aw4.cmp_passed + u_aw6.passed + u_aw6.cmp_passed
              + u_aw8.passed + u_aw8.cmp_passed;
    wd_failed = u_aw4.failed + u_aw4.cmp_failed + u_aw6.failed + u_aw6.cmp_failed
              + u_aw8.failed + u_aw8.cmp_failed + 1;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, wd_passed, wd_failed);
    $finish;
  end

endmodule
